/** Normaliza un nombre de habilidad a una clave estable de los mapas. */
function toAbilityKey(name: string): string {
  return name
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

/** Devuelve la descripción en español de una habilidad, si existe. */
export function getAbilityDescription(name: string): string | undefined {
  return ABILITY_DESCRIPTIONS_ES[toAbilityKey(name)];
}

/** Devuelve los efectos fuera de combate de una habilidad, si tiene. */
export function getOutOfBattleEffects(name: string): string[] {
  return OUT_OF_BATTLE_EFFECTS_ES[toAbilityKey(name)] ?? [];
}
